import re
from pathlib import Path
text=Path('/root/latex_paper.txt').read_text()
pages=text.split('\f')
math_re=re.compile(r"[=\\^_]|\b(?:sin|cos|exp)\b|[\u03b1-\u03c9\u0394\u03a9\u03a3\u03c0\u00b1\u00b5]|\u2113|\u03b7|\u03c1|\u03c4|\u03b4|\u03bb|\u03b3|\u03be|\u03b8|\u03ba|\u03c6|\u03c7|\u03c8")
for pi,page in enumerate(pages, start=1):
    lines=page.splitlines()
    for i,line in enumerate(lines):
        stripped=line.strip()
        if not stripped:
            continue
        if math_re.search(stripped):
            # heuristic: line has few letters and many symbols OR is centered (leading spaces)
            letters=sum(ch.isalpha() for ch in stripped)
            symbols=sum(ch in '=+-*/^_()[]{}' for ch in stripped)
            if letters<=15 or symbols>=2 or stripped.startswith('d2') or 'Pe (t)' in stripped or 'Hi,M' in stripped:
                print(f'page {pi} line {i+1}: {line}')
